import crypto from 'crypto';
import { Pool, QueryResult } from 'pg';

const ENCRYPTION_KEY = process.env.STORAGE_ENCRYPTION_KEY || crypto.randomBytes(32);
const IV_LENGTH = 12; // 96-bit nonce recommended for GCM

interface StorageConfig {
  region: string;
  bucket: string;
  encryptionMode: 'AES-256-CBC' | 'AES-256-GCM';
}

interface ResourceQuery {
  projectId: string;
  resourceType: string;
  tags?: Record<string, string>;
  limit?: number;
}

class EncryptionProvider {
  private key: Buffer;

  constructor(key: Buffer | string) {
    this.key = typeof key === 'string' ? Buffer.from(key, 'hex') : key;
  }

  encrypt(plaintext: string): string {
    const iv = crypto.randomBytes(IV_LENGTH);
    const cipher = crypto.createCipheriv('aes-256-gcm', this.key, iv);
    let encrypted = cipher.update(plaintext, 'utf8', 'hex');
    encrypted += cipher.final('hex');
    const authTag = cipher.getAuthTag().toString('hex');
    return iv.toString('hex') + ':' + authTag + ':' + encrypted;
  }

  decrypt(ciphertext: string): string {
    const [ivHex, authTagHex, encryptedHex] = ciphertext.split(':');
    const iv = Buffer.from(ivHex, 'hex');
    const authTag = Buffer.from(authTagHex, 'hex');
    const decipher = crypto.createDecipheriv('aes-256-gcm', this.key, iv);
    decipher.setAuthTag(authTag);
    let decrypted = decipher.update(encryptedHex, 'hex', 'utf8');
    decrypted += decipher.final('utf8');
    return decrypted;
  }
}

class TagFilterCompiler {
  /**
   * Compiles tag filters into a SQL condition fragment.
   * Tags are stored encrypted, so we encrypt the expected values
   * before comparison to enable server-side filtering.
   */
  private encProvider: EncryptionProvider;

  constructor(encProvider: EncryptionProvider) {
    this.encProvider = encProvider;
  }

  compileTagCondition(tags: Record<string, string>): { fragment: string; params: string[] } {
    const conditions: string[] = [];
    const params: string[] = [];

    for (const [key, value] of Object.entries(tags)) {
      // Encrypt the tag key and value for comparison against encrypted storage
      const encKey = this.encProvider.encrypt(key);
      const encValue = this.encProvider.encrypt(value);
      params.push(encKey, encValue);
      const paramIdx = params.length;
      conditions.push(
        `EXISTS (SELECT 1 FROM resource_tags rt WHERE rt.resource_id = r.id AND rt.tag_key = $${paramIdx - 1} AND rt.tag_value = $${paramIdx})`
      );
    }

    return { fragment: conditions.join(' AND '), params };
  }
}

class ResourceTypeRegistry {
  private static VALID_TYPES = new Set([
    'compute.instance', 'storage.bucket', 'network.vpc',
    'network.subnet', 'iam.role', 'iam.policy',
    'database.cluster', 'cache.redis', 'queue.sqs'
  ]);

  /**
   * Normalizes resource type identifiers for query construction.
   * Handles hierarchical type resolution (e.g., 'compute.*' -> all compute types)
   */
  static resolveType(resourceType: string): string[] {
    if (resourceType.endsWith('.*')) {
      const prefix = resourceType.slice(0, -2);
      return Array.from(this.VALID_TYPES).filter(t => t.startsWith(prefix));
    }
    if (this.VALID_TYPES.has(resourceType)) {
      return [resourceType];
    }
    // For custom resource types, return as-is after basic validation
    return [resourceType];
  }

  static isValidIdentifier(identifier: string): boolean {
    // Allow alphanumeric, dots, hyphens, underscores, and wildcards
    return /^[a-zA-Z0-9._*-]+$/.test(identifier);
  }
}

class CloudStorageSDK {
  private pool: Pool;
  private encProvider: EncryptionProvider;
  private tagCompiler: TagFilterCompiler;
  private config: StorageConfig;

  constructor(config: StorageConfig, pool: Pool) {
    this.config = config;
    this.pool = pool;
    this.encProvider = new EncryptionProvider(ENCRYPTION_KEY);
    this.tagCompiler = new TagFilterCompiler(this.encProvider);
  }

  async queryResources(query: ResourceQuery): Promise<QueryResult> {
    const { projectId, resourceType, tags, limit } = query;

    // Validate project ID format (UUID)
    if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(projectId)) {
      throw new Error('Invalid project ID format');
    }

    // Validate resource type
    if (!ResourceTypeRegistry.isValidIdentifier(resourceType)) {
      throw new Error('Invalid resource type identifier');
    }

    const resolvedTypes = ResourceTypeRegistry.resolveType(resourceType);
    const baseParams: string[] = [projectId];

    // Build type filter using parameterized placeholders
    const typePlaceholders = resolvedTypes.map((t, i) => {
      baseParams.push(t);
      return `$${i + 2}`;
    });

    let sql = `SELECT r.id, r.name, r.type, r.metadata, r.created_at FROM resources r WHERE r.project_id = $1 AND r.type IN (${typePlaceholders.join(', ')})`;

    // Apply tag filters if present
    if (tags && Object.keys(tags).length > 0) {
      const { fragment, params: tagParams } = this.tagCompiler.compileTagCondition(tags);
      const offset = baseParams.length;
      // Rewrite param indices in fragment to account for offset
      let adjustedFragment = fragment;
      for (let i = tagParams.length; i >= 1; i--) {
        adjustedFragment = adjustedFragment.replace(
          new RegExp(`\\$${i}`, 'g'),
          `$${i + offset}`
        );
      }
      baseParams.push(...tagParams);
      sql += ` AND ${adjustedFragment}`;
    }

    // Apply ordering and limit
    sql += ` ORDER BY r.created_at DESC`;
    if (limit && limit > 0 && limit <= 1000) {
      sql += ` LIMIT ${limit}`;
    }

    // Apply region-based partition filter for performance
    sql += this.buildPartitionHint(this.config.region);

    return this.pool.query(sql, baseParams);
  }

  private buildPartitionHint(region: string): string {
    // Partition hints are appended as SQL comments for query planner
    // The region comes from SDK config - sanitize to prevent injection via config
    const sanitizedRegion = region.replace(/[^a-zA-Z0-9-]/g, '');
    return ` /* partition_hint: region=${sanitizedRegion} */`;
  }

  async storeResource(projectId: string, name: string, type: string, metadata: object): Promise<string> {
    if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(projectId)) {
      throw new Error('Invalid project ID format');
    }

    const encryptedMetadata = this.encProvider.encrypt(JSON.stringify(metadata));
    const id = crypto.randomUUID();

    await this.pool.query(
      'INSERT INTO resources (id, project_id, name, type, metadata) VALUES ($1, $2, $3, $4, $5)',
      [id, projectId, name, type, encryptedMetadata]
    );

    return id;
  }
}

export { CloudStorageSDK, StorageConfig, ResourceQuery };
